                    selected: isSelected,
                    'range-selection': isRangeSelection,
                    'selection-start': isSelectionStart,
                    'selection-end': isSelectionEnd,
                    'out-of-boundary': isOutsideCurrentRange,
                    unavailable: isUnavailable,
                    current: isCurrent,
                    weekend: isWeekend,
                })}
            >
                {formattedDate}
            </div>
        </div>
    );
}
